<?php /** @var array $files @var array $o @var string $tq */ $ifiles = $files; ?>
<?php $edit = feature('files.manage') && order_files_editable($o); ?><div style="font-size:14px;margin:8px 0 0"><?php foreach ($ifiles as $f): ?><div style="margin:0 0 8px"><?= ic('file') ?> <a href="/fichier/<?= (int) $f['id'] ?><?= $tq ?>"><?= e($f['orig_name']) ?></a> <small class="muted"><?= Files::human((int) $f['size']) ?><?= !empty($f['width']) ? ' · ' . (int) $f['width'] . '×' . (int) $f['height'] . ' px' : '' ?></small> <?= status_badge(Files::STATUS, $f['status']) ?>
        <?php if (!empty($f['warn'])): ?><br><small style="color:#b3261e">⚠ <?= e($f['warn']) ?></small><?php endif; ?>
        <?php if ($edit): ?><details style="display:inline-block;margin-left:8px"><summary style="cursor:pointer;color:var(--p)">Remplacer</summary><form method="post" action="/commande/<?= e($o['ref']) ?>/fichier/<?= (int) $f['id'] ?>/remplacer<?= $tq ?>" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="t" value="<?= e($o['access_token']) ?>"><input type="file" name="file" required> <button class="btn btn-g btn-sm" type="submit">Envoyer le nouveau fichier</button></form></details>
        <details style="display:inline-block;margin-left:8px"><summary style="cursor:pointer;color:#b3261e">Supprimer</summary><form method="post" action="/commande/<?= e($o['ref']) ?>/fichier/<?= (int) $f['id'] ?>/supprimer<?= $tq ?>"><?= csrf_field() ?><input type="hidden" name="t" value="<?= e($o['access_token']) ?>"><button class="btn btn-d btn-sm" type="submit">Confirmer la suppression</button></form></details><?php endif; ?></div><?php endforeach; ?>
        <?php if (!$edit && feature('files.manage')): ?><small class="muted">Fichiers verrouillés : la production est lancée. Pour une modification, contactez-nous.</small><?php endif; ?></div>
